  $: name = iconClass.split(/\s+/).find(token => token.startsWith('ph-') && !['ph-fill', 'ph-duotone'].includes(token))?.slice(3) || 'house';
  $: weight = iconClass.includes('ph-fill') ? '-fill' : iconClass.includes('ph-duotone') ? '-duotone' : '';
  $: artwork = icons[name + weight] || icons[name] || icons.house;
</script>

